using System.Net;
using LinguaPath.Domain.Entities;
using LinguaPath.Shared;

namespace LinguaPath.Infrastructure.Persistence.Seed;

/// <summary>
/// Development-only lesson text for the sample Spanish roadmap, so the reader can be tried end to end.
/// Real lectures are written in the admin panel (or generated by AI in Phase 5).
/// </summary>
internal static class SampleLectureContent
{
    private sealed record Sample(string Body, (string Target, string Translation)[] Examples, (string Word, string Meaning, string Pron)[] Words);

    private static readonly Dictionary<string, Sample> ByTitle = new()
    {
        ["Greetings and goodbyes"] = new(
            """
            <h2>Saying hello</h2>
            <p>Spanish greetings change with the time of day. <strong>Hola</strong> works any time and with anyone.</p>
            <table><thead><tr><th>Spanish</th><th>When</th></tr></thead>
            <tbody><tr><td>Buenos días</td><td>Morning, until lunch</td></tr>
            <tr><td>Buenas tardes</td><td>Afternoon, until dark</td></tr>
            <tr><td>Buenas noches</td><td>Evening and night (also "good night")</td></tr></tbody></table>
            <h2>Saying goodbye</h2>
            <p><strong>Adiós</strong> is goodbye; <strong>hasta luego</strong> (see you later) is more common in everyday life.</p>
            <blockquote>Tip: in Spain friends often greet with two kisses on the cheek, starting on the right.</blockquote>
            """,
            [("Hola, ¿qué tal?", "Hi, how are you?"), ("Buenos días, señora.", "Good morning, madam."), ("Hasta luego, Ana.", "See you later, Ana.")],
            [("hola", "hello", "OH-lah"), ("adiós", "goodbye", "ah-DYOS"), ("hasta luego", "see you later", "AHS-tah LWEH-goh")]),

        ["Ser: I am, you are"] = new(
            """
            <h2>The verb <em>ser</em> (to be)</h2>
            <p>Use <strong>ser</strong> for who someone is: name, nationality, job and lasting characteristics.</p>
            <table><thead><tr><th>Person</th><th>Ser</th></tr></thead>
            <tbody><tr><td>yo</td><td>soy</td></tr><tr><td>tú</td><td>eres</td></tr><tr><td>él / ella / usted</td><td>es</td></tr>
            <tr><td>nosotros</td><td>somos</td></tr><tr><td>vosotros</td><td>sois</td></tr><tr><td>ellos / ustedes</td><td>son</td></tr></tbody></table>
            <h3>Common mistakes</h3>
            <ul><li>Spanish usually drops the pronoun: <em>Soy Ana</em>, not always <em>Yo soy Ana</em>.</li>
            <li>For location and feelings Spanish uses <em>estar</em>, which you'll meet in module 4.</li></ul>
            """,
            [("Soy profesora.", "I am a teacher."), ("¿Eres de México?", "Are you from Mexico?"), ("Somos amigos.", "We are friends.")],
            [("ser", "to be (identity)", "sehr"), ("profesor / profesora", "teacher", "proh-feh-SOR"), ("amigo", "friend", "ah-MEE-goh")]),

        ["Numbers 0-20"] = new(
            """
            <h2>Counting to twenty</h2>
            <p>0 cero, 1 uno, 2 dos, 3 tres, 4 cuatro, 5 cinco, 6 seis, 7 siete, 8 ocho, 9 nueve, 10 diez.</p>
            <p>11 once, 12 doce, 13 trece, 14 catorce, 15 quince, 16 dieciséis, 17 diecisiete, 18 dieciocho, 19 diecinueve, 20 veinte.</p>
            <p><strong>Uno</strong> becomes <strong>un</strong> before a masculine noun and <strong>una</strong> before a feminine one.</p>
            """,
            [("Tengo dos hermanos.", "I have two brothers."), ("Son las diez.", "It's ten o'clock."), ("Un café, por favor.", "A coffee, please.")],
            [("uno", "one", "OO-noh"), ("diez", "ten", "dyehs"), ("veinte", "twenty", "BAYN-teh")])
    };

    /// <summary>Fills lectures of the sample course that have no text yet.</summary>
    public static void Fill(IEnumerable<Lecture> lectures)
    {
        foreach (var lecture in lectures.Where(l => string.IsNullOrWhiteSpace(l.BodyHtml)))
        {
            if (ByTitle.TryGetValue(lecture.Title, out var sample))
            {
                lecture.BodyHtml = sample.Body.Trim();
                for (var i = 0; i < sample.Examples.Length; i++)
                    lecture.Examples.Add(new LectureExample { TargetText = sample.Examples[i].Target, Translation = sample.Examples[i].Translation, SortOrder = i + 1 });
                for (var i = 0; i < sample.Words.Length; i++)
                    lecture.Vocabulary.Add(new LectureVocabulary { Word = sample.Words[i].Word, Meaning = sample.Words[i].Meaning, Pronunciation = sample.Words[i].Pron, SortOrder = i + 1 });
            }
            else
            {
                var title = WebUtility.HtmlEncode(lecture.Title);
                lecture.BodyHtml = $"""
                    <h2>{title}</h2>
                    <p>This is sample text for <strong>{title}</strong>. Replace it from the admin panel: Lectures → Edit content.</p>
                    <ul><li>Read the explanation.</li><li>Listen to the examples.</li><li>Mark the lecture as complete.</li></ul>
                    """;
                lecture.Examples.Add(new LectureExample { TargetText = "¿Puedes repetir, por favor?", Translation = "Can you repeat, please?", SortOrder = 1 });
            }
            lecture.Status = ContentStatus.Published;
            lecture.PublishedAt ??= DateTimeOffset.UtcNow;
        }
        // One example link on the first lecture.
        var first = lectures.FirstOrDefault(l => l.Title == "The Spanish alphabet and sounds");
        if (first is not null && first.Links.Count == 0)
            first.Links.Add(new LectureLink { Title = "Spanish alphabet (Wikipedia)", Url = "https://en.wikipedia.org/wiki/Spanish_orthography", LinkType = LinkType.Article, SortOrder = 1 });
    }

    public static IEnumerable<Post> Posts(int languageId, DateTimeOffset now) =>
    [
        new() { LanguageId = languageId, PostType = PostType.WordOfTheDay, Title = "Word of the day: madrugada", Body = "The early hours after midnight, before sunrise. \"Llegamos de madrugada\" — we arrived in the small hours.", Level = CefrLevel.A2, Status = ContentStatus.Published, PublishAt = now, IsPinned = true },
        new() { LanguageId = languageId, PostType = PostType.Tip, Title = "Learn words in pairs", Body = "Learn opposites together: grande / pequeño, caro / barato, abrir / cerrar. They stick better.", Level = CefrLevel.A1, Status = ContentStatus.Published, PublishAt = now.AddHours(-2) },
        new() { LanguageId = languageId, PostType = PostType.CulturalNote, Title = "Why dinner is so late in Spain", Body = "Many Spaniards eat lunch around 2–3 pm and dinner after 9 pm. Restaurants may be empty at 7!", Level = CefrLevel.A1, Status = ContentStatus.Published, PublishAt = now.AddDays(-1) },
        new() { LanguageId = languageId, PostType = PostType.Article, Title = "Ser vs estar explained", Url = "https://en.wikipedia.org/wiki/Romance_copula", Body = "A longer read on the two Spanish verbs for 'to be'.", Level = CefrLevel.A2, Status = ContentStatus.Published, PublishAt = now.AddDays(-2) }
    ];
}
